//! `sp_engine::ground` reproduces the Ground mockup exactly (ENG-5, GD-2, GD-5, DONE-2).
//!
//! `ground_goldens.json` holds what `docs/design/mockup/Ground.dc.html`'s own `calc()` and
//! `renderVals()` produce for 130 states (the default, every soil × foundation, the scenarios
//! at years 0 / 0.25 / 30, Pisa fixes, the 30 m rock edge, a seeded sample), generated by
//! `node crates/sp-engine/tests/tower_ground_goldens.mjs`.

use serde_json::Value;
use sp_engine::ground::{self, Foundation, GroundInput, SCENARIOS, Soil, Status};
use sp_engine::tower::fmt::fixed;

fn goldens() -> Vec<Value> {
    serde_json::from_str(include_str!("ground_goldens.json")).expect("valid golden JSON")
}

fn input_of(st: &Value) -> GroundInput {
    GroundInput {
        soil: Soil::from_key(st["soil"].as_str().unwrap()).unwrap(),
        foundation: Foundation::from_key(st["found"].as_str().unwrap()).unwrap(),
        floors: st["floors"].as_u64().unwrap() as u32,
        pile_len: st["pileL"].as_f64().unwrap(),
        quake: st["quake"].as_bool().unwrap(),
        years: st["t"].as_f64().unwrap(),
        pisa_tried: st["pisaTried"].as_bool().unwrap(),
    }
}

fn close(a: f64, b: f64, what: &str, ctx: &str) {
    let tol = 1e-12 * a.abs().max(b.abs()).max(1e-300);
    assert!((a - b).abs() <= tol, "{ctx}: {what} {a} vs mockup {b}");
}

#[test]
fn every_golden_state_matches_the_mockup() {
    let all = goldens();
    assert!(all.len() >= 100, "{} states", all.len());
    for g in &all {
        let input = input_of(&g["state"]);
        let ctx = format!("{:?}", g["state"]);
        let r = ground::calc(&input);
        let c = &g["calc"];
        close(r.load, c["load"].as_f64().unwrap(), "load", &ctx);
        close(r.pressure, c["q"].as_f64().unwrap(), "q", &ctx);
        close(r.capacity, c["cap"].as_f64().unwrap(), "cap", &ctx);
        close(r.fs, c["FS"].as_f64().unwrap(), "FS", &ctx);
        assert_eq!(r.deep, c["deep"].as_bool().unwrap(), "{ctx}");
        assert_eq!(r.to_rock, c["toRock"].as_bool().unwrap(), "{ctx}");
        assert_eq!(r.liquefied, c["liquefied"].as_bool().unwrap(), "{ctx}");
        close(
            r.settle_final,
            c["settleF"].as_f64().unwrap(),
            "settleF",
            &ctx,
        );
        close(r.tilt_final, c["tiltF"].as_f64().unwrap(), "tiltF", &ctx);
        close(r.settle, c["settle"].as_f64().unwrap(), "settle", &ctx);
        close(r.tilt, c["tilt"].as_f64().unwrap(), "tilt", &ctx);
        close(r.tau, c["tau"].as_f64().unwrap(), "tau", &ctx);

        for (t, gt) in ground::tiles(&input, &r)
            .iter()
            .zip(g["tiles"].as_array().unwrap())
        {
            assert_eq!(t.key, gt["k"], "{ctx}");
            assert_eq!(t.value, gt["v"], "{ctx}: {}", t.key);
            assert_eq!(t.note, gt["n"], "{ctx}: {}", t.key);
            assert_eq!(t.tone.css(), gt["c"], "{ctx}: {} colour", t.key);
        }
        let status = Status::of(&r);
        assert_eq!(status.label(), g["status"], "{ctx}");
        assert_eq!(status.tone().css(), g["statusColor"], "{ctx}");
        assert_eq!(ground::fs_text(&r), g["fsText"], "{ctx}");
        assert_eq!(ground::fs_tone(&r).css(), g["fsColor"], "{ctx}");
        assert_eq!(fixed(ground::fs_pos(&r), 1), g["fsPos"], "{ctx}");
        for (gl, gg) in ground::goals(&input)
            .iter()
            .zip(g["goals"].as_array().unwrap())
        {
            assert_eq!(gl.text, gg["text"], "{ctx}");
            assert_eq!(gl.done, gg["done"].as_bool().unwrap(), "{ctx}: {}", gl.text);
        }
        assert_eq!(ground::explain(&input, &r), g["explain"], "{ctx}");
        assert_eq!(
            ground::stage_chip(&r),
            format!(
                "tilt {} · sank {}",
                g["tiltNow"].as_str().unwrap(),
                g["settleNow"].as_str().unwrap()
            ),
            "{ctx}"
        );
        assert_eq!(ground::year_label(input.years), g["yearLabel"], "{ctx}");
        assert_eq!(ground::clock(input.years), g["clock"], "{ctx}");
        assert_eq!(ground::pile_label(input.pile_len), g["pileLabel"], "{ctx}");
        assert_eq!(ground::stage_label(&input, &r), g["stageLabel"], "{ctx}");
        assert_eq!(input.soil.def().name.to_lowercase(), g["soilName"], "{ctx}");
        assert_eq!(input.soil.wet(), g["wet"].as_bool().unwrap(), "{ctx}");
    }
}

/// The numbers in the reference screenshot `docs/design/screenshots/Ground-1440.png`.
#[test]
fn the_default_state_shows_the_reference_numbers() {
    let input = GroundInput::default();
    let r = ground::calc(&input);
    let values: Vec<String> = ground::tiles(&input, &r)
        .iter()
        .map(|t| t.value.clone())
        .collect();
    assert_eq!(
        values,
        ["72 kPa", "60 kPa", "268 mm", "2.37°", "115 MN", "9 yr"]
    );
    assert_eq!(ground::tiles(&input, &r)[2].note, "heads to 400 mm");
    assert_eq!(ground::fs_text(&r), "0.83 · target 3");
    assert_eq!(ground::stage_chip(&r), "tilt 2.37° · sank 268 mm");
    assert_eq!(ground::clock(input.years), "year 10.0");
    assert_eq!(Status::of(&r).label(), "Bearing failure");
}

/// GD-1 / DONE-4: load the leaning tower, then fix it with piles (or caissons, or a deeper
/// pile to rock) without removing floors: all three goals light.
#[test]
fn the_pisa_challenge_is_completable() {
    let start = SCENARIOS[0].apply(&GroundInput::default());
    assert!(start.pisa_tried && start.years == 0.0 && start.floors == 6);
    let goals = ground::goals(&start);
    assert_eq!(goals.map(|g| g.done), [true, true, false]);

    for fix in [
        GroundInput {
            foundation: Foundation::Piles,
            pile_len: 34.0,
            ..start
        },
        GroundInput {
            foundation: Foundation::Caisson,
            ..start
        },
    ] {
        assert_eq!(ground::goals(&fix).map(|g| g.done), [true, true, true]);
    }
    // Short friction piles in soft clay don't fix it.
    let short = GroundInput {
        foundation: Foundation::Piles,
        pile_len: 8.0,
        ..start
    };
    assert!(!ground::goals(&short)[2].done);
    // Removing floors breaks goal 2.
    let fewer = GroundInput { floors: 5, ..start };
    assert!(!ground::goals(&fewer)[1].done);
}

#[test]
fn scenarios_and_play_years() {
    let names: Vec<&str> = SCENARIOS.iter().map(|s| s.name).collect();
    assert_eq!(
        names,
        [
            "Leaning tower (soft clay, mat)",
            "Liquefaction (wet sand + quake)",
            "60 floors on piles to rock",
            "Friction piles in soft clay"
        ]
    );
    let liq = SCENARIOS[1].apply(&GroundInput::default());
    assert_eq!(
        Status::of(&ground::calc(&GroundInput { years: 0.25, ..liq })),
        Status::Liquefaction
    );
    // Play years: 0.25 per tick up to 30, then stops; a restart from 30 begins at 0.
    let mut y = ground::play_start(30.0);
    assert_eq!(y, 0.0);
    let mut ticks = 0;
    while let Some(n) = ground::play_tick(y) {
        y = n;
        ticks += 1;
    }
    assert_eq!((y, ticks), (30.0, 120));
    assert_eq!(ground::play_start(12.5), 12.5);
}

#[test]
fn share_line_is_one_soil_line() {
    let input = GroundInput::default();
    let r = ground::calc(&input);
    assert_eq!(
        ground::share_line(&input, &r),
        ".soil 1 30 soft-clay  .foundation mat  ; 6 floors · quake off · year 10.0 · FS 0.83 · \
         tilt 2.37° · sank 268 mm"
    );
    let piles = GroundInput {
        foundation: Foundation::Piles,
        ..input
    };
    assert!(ground::share_line(&piles, &ground::calc(&piles)).contains(".foundation piles 34 6"));
}
